package com.gmail.absolutebollockscreations.gattlibrary.central

import org.junit.Assert.assertArrayEquals
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * Envelope-level tests for [FeCFrameCodec], per plan §16.2.
 *
 * The pinned vector in [decode returns the Tacx PDF worked example] is the one piece of
 * external evidence here (`docs/How-to FE-C over BLE v1_0_0.pdf` page 5); every other vector
 * is generated by [FeCFrameCodec.encode] itself and then round-tripped through [decode],
 * which only proves internal self-consistency - it cannot substitute for the pinned vector
 * as evidence that the checksum algorithm matches the real protocol.
 */
class FeCFrameCodecTest {

    private fun bytes(vararg v: Int) = ByteArray(v.size) { (v[it] and 0xFF).toByte() }

    @Test
    fun `decode returns the Tacx PDF worked example`() {
        val wire = bytes(0xA4, 0x09, 0x4F, 0x05, 0x33, 0xFF, 0xFF, 0xFF, 0xFF, 0x20, 0x4E, 0x42, 0xF8)
        val result = FeCFrameCodec.decode(wire)
        val decoded = result as? FeCFrameDecodeResult.Decoded ?: error("expected Decoded, got $result")
        assertEquals(0x4F, decoded.frame.messageType)
        assertEquals(0x05, decoded.frame.channel)
        assertArrayEquals(bytes(0x33, 0xFF, 0xFF, 0xFF, 0xFF, 0x20, 0x4E, 0x42), decoded.frame.data)
    }

    @Test
    fun `encode then decode round-trips`() {
        val payload = bytes(0x10, 25, 40, 120, 0x88, 0x13, 145, 0x34)
        val wire = FeCFrameCodec.encode(0x4E, 5, payload)
        val decoded = FeCFrameCodec.decode(wire) as? FeCFrameDecodeResult.Decoded
            ?: error("expected Decoded")
        assertEquals(0x4E, decoded.frame.messageType)
        assertEquals(5, decoded.frame.channel)
        assertArrayEquals(payload, decoded.frame.data)
    }

    @Test
    fun `rejects fewer than 5 bytes`() {
        val result = FeCFrameCodec.decode(bytes(0xA4, 0x00, 0x00, 0x00))
        assertEquals(
            FeCFrameRejection.TOO_SHORT,
            (result as FeCFrameDecodeResult.Rejected).reason,
        )
    }

    @Test
    fun `rejects wrong sync byte`() {
        val wire = FeCFrameCodec.encode(0x4E, 5, bytes(0x10, 25, 40, 120, 0x88, 0x13, 145, 0x34))
        wire[0] = 0xA5.toByte()
        val result = FeCFrameCodec.decode(wire)
        assertEquals(FeCFrameRejection.BAD_SYNC, (result as FeCFrameDecodeResult.Rejected).reason)
    }

    @Test
    fun `rejects declared length mismatched with actual size`() {
        val wire = FeCFrameCodec.encode(0x4E, 5, bytes(0x10, 25, 40, 120, 0x88, 0x13, 145, 0x34))
        val truncated = wire.copyOf(wire.size - 1)
        val result = FeCFrameCodec.decode(truncated)
        assertEquals(FeCFrameRejection.BAD_LENGTH, (result as FeCFrameDecodeResult.Rejected).reason)
    }

    @Test
    fun `rejects a valid frame truncated at every boundary`() {
        val wire = FeCFrameCodec.encode(0x4E, 5, bytes(0x10, 25, 40, 120, 0x88, 0x13, 145, 0x34))
        for (size in 0 until wire.size) {
            assertTrue("truncation size=$size", FeCFrameCodec.decode(wire.copyOf(size)) is FeCFrameDecodeResult.Rejected)
        }
    }

    @Test
    fun `rejects an extra trailing byte`() {
        val wire = FeCFrameCodec.encode(0x4E, 5, bytes(0x10, 25, 40, 120, 0x88, 0x13, 145, 0x34))
        assertEquals(
            FeCFrameRejection.BAD_LENGTH,
            (FeCFrameCodec.decode(wire + 0x00) as FeCFrameDecodeResult.Rejected).reason,
        )
    }

    @Test
    fun `rejects checksum mismatch`() {
        val wire = FeCFrameCodec.encode(0x4E, 5, bytes(0x10, 25, 40, 120, 0x88, 0x13, 145, 0x34))
        wire[wire.size - 1] = (wire[wire.size - 1].toInt() xor 0x01).toByte()
        val result = FeCFrameCodec.decode(wire)
        assertEquals(FeCFrameRejection.BAD_CHECKSUM, (result as FeCFrameDecodeResult.Rejected).reason)
    }

    @Test
    fun `rejects unsupported message type`() {
        val wire = FeCFrameCodec.encode(0x40, 5, bytes(0x10, 25, 40, 120, 0x88, 0x13, 145, 0x34))
        val result = FeCFrameCodec.decode(wire)
        assertEquals(
            FeCFrameRejection.UNSUPPORTED_MESSAGE_TYPE,
            (result as FeCFrameDecodeResult.Rejected).reason,
        )
    }

    @Test
    fun `rejects a known page declared with fewer than 8 payload bytes`() {
        val wire = bytes(0xA4, 0x05, 0x4E, 0x05, 0x10, 0x01, 0x02, 0x03, 0xFA)
        val result = FeCFrameCodec.decode(wire)
        assertEquals(
            FeCFrameRejection.SHORT_KNOWN_PAGE,
            (result as FeCFrameDecodeResult.Rejected).reason,
        )
    }

    @Test
    fun `does not apply modulo to the running checksum`() {
        // Regression guard for the Incyclist `% 0xFF` defect (plan §3.2): pick a payload whose
        // XOR accumulator legitimately passes through 0xFF partway through, which a `% 0xFF`
        // step would corrupt into 0x00 and desync every subsequent XOR.
        val payload = bytes(0x10, 0xFF, 0x00, 0xFF, 0x00, 0xFF, 0x00, 0xFF)
        val wire = FeCFrameCodec.encode(0x4E, 5, payload)
        val decoded = FeCFrameCodec.decode(wire)
        assertTrue(decoded is FeCFrameDecodeResult.Decoded)
    }
}
